const answerLocationsSerialized = new Set<string>();
const almostPalindromeLocationsSerialized = new Set<string>();
const answerIndexMap = clueAnswers.reduce<Record<string, number>>(
  (acc, [answer, _], index) => {
    acc[answer] = index;
    return acc;
  },
  {},
);
for (const [answer, _] of clueAnswers) {
  const coords = answerLocations[answer];
  const answerIndex = answerIndexMap[answer];
  if (!coords || !answerIndex) continue;
  for (const [letterIndex, { row, col }] of coords.entries()) {
    if (letterIndex === almostPalindromeIndex[answerIndex]) {
      almostPalindromeLocationsSerialized.add(`${row},${col}`);
    } else {
      answerLocationsSerialized.add(`${row},${col}`);
    }
  }
}

const defaultCellBg: Record<string, string> = {};
Object.entries(answerLocations).forEach(([_, coords], index) => {
  const color = backgroundColors[index] ?? "";
  const extractIndex: number = almostPalindromeIndex[index] ?? -1;
  for (const [letterIndex, { row, col }] of coords.entries()) {
    if (letterIndex === extractIndex) {
      defaultCellBg[`${row},${col}`] = "bg-slate-700 text-white font-bold";
    }
    defaultCellBg[`${row},${col}`] ??= color;
  }
});

const WordList = ({
  clues,
  clueAnswers,
  backgroundColors,
  highlightedIndex,
  onHover,
  onLeave,
}: {
  clues: string[];
  clueAnswers: [string, string][];
  backgroundColors: string[];
  highlightedIndex: number;
  onHover: (i: number) => void;
  onLeave: () => void;
}) => {
  return (
    <table>
      <thead>
        <tr>
          <th className="border-black border">Clue</th>{" "}
          <th className="border-black border">Answer</th>
          <th className="border-black border">Removed Letter</th>
        </tr>
      </thead>
      <tbody>
        {clues.map((clue, i) => (
          <tr
            className={`${backgroundColors[i] ?? ""} ${
              i === highlightedIndex ? "ring-2 ring-black ring-inset" : ""
            }`}
            key={clueAnswers[i][0]}
            tabIndex={0}
            onFocus={() => {
              onHover(i);
            }}
            onBlur={() => {
              onLeave();
            }}
            onMouseEnter={() => {
              onHover(i);
            }}
            onMouseLeave={() => {
              onLeave();
            }}
            style={{ cursor: "pointer", marginBottom: "8px" }}
          >
            <td className="px-2 border-black border">{clue}</td>
            <td className="px-2 border-black border">
              <Mono>{clueAnswers[i][0]} </Mono>
            </td>
            <td className="px-2 border-black border">
              <Mono>{clueAnswers[i][1]} </Mono>
            </td>
          </tr>
        ))}
      </tbody>
    </table>
  );
};

export const WordSearchSolution = () => {
  const [highlightedIndex, setHighlightedIndex] = useState<number>(-1);
  const [highlightedPositions, setHighlightedPositions] = useState<
    { row: number; col: number }[]
  >([]);

  return (
    <div className="grid grid-cols-3">
      <div className="col-span-2 place-self-center">
        <HighlightedBorderedGrid
          grid={grid}
          defaultCellBg={defaultCellBg}
          highlightedPositions={highlightedPositions}
          className="py-1 px-2 text-center"
        />
      </div>
      <div>
        <p>Hover or keyboard-focus to highlight in grid</p>
        <WordList
          clues={clues}
          clueAnswers={clueAnswers}
          backgroundColors={backgroundColors}
          highlightedIndex={highlightedIndex}
          onHover={(i: number) => {
            setHighlightedIndex(i);
            const key = clueAnswers[i][0];
            if (key && key in answerLocations) {
              const positions = answerLocations[key];
              if (positions) {
                setHighlightedPositions(positions);
              }
            }
          }}
          onLeave={() => {
            setHighlightedIndex(-1);
            setHighlightedPositions([]);
          }}
        />
      </div>
    </div>
  );
};
